updateSortIndicator(column) {
  this.treeTable.header
    .querySelector("[aria-sort]")
    ?.removeAttribute("aria-sort");

  const header = this.treeTable.header.querySelector(`#${column}`);
  if (header) {
    header.ariaSort = gViewWrapper.isSortedAscending
      ? "ascending"
      : "descending";
  }
},
